function UIFishPoolFishAltasItemNode:Refresh(data, cb, type)
    if not data then
        return
    end

    if not self._goodNodeScr then 
        self._goodNodeScr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    end
    self._data = data
    self._cb = cb

    self:RefreshSelectActive(false)
    KTool.SetActive(self.Fishking, false)
    if type == Type.Atlas then
        self:FillAtlasInfo()
    else
        self:FillEggsInfo()
    end
end

function UIFishPoolFishAltasItemNode:FillAtlasInfo(data, cb)
    KTool.SetActive(self.ImageNew, false)
    self:RefreshSelectActive(false)
    CfUtils.RefeshGoodGo(self.GoodNode, self._data.id, nil, 0.75, nil, function()
    end)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.id)
    --CfUtils.FillImage(self.GoodNode.transform:Find("Container/Bg"), GoodsUtils.GetFishBgByQualityType(goodsVo.quality))
    SetButtonAction(self.Button, function()
        fishingComponent:DelNewPointFish(self._data.id)
        KTool.SetActive(self.ImageNew, false)
        if self._cb then
            self._cb()
        end
    end)

    local isCollect = FishingUtils.IsCollectionGetFishById(self._data.id)
    KTool.SetActive(self.NotGet, not isCollect)
    --KTool.SetActive(self.GoodNode, isCollect)
    KTool.SetActive(self.FishGrade, isCollect)

    if isCollect then
        KTool.SetActive(self.Fishking, checkNumber(self._data.isKing) == 1)

        local dojo = fishingComponent:GetFishCollectionDojoByFishId(self._data.id)
        CfUtils.SetUISwitchImage(self.TextGrade, (dojo.rating))
        CfUtils.SetUISwitchImage(self.ImgIcon, FishingUtils.GetFishRareNameByRare(dojo.rating) == "S" and 2 or 1)
    end
    local isNew = FishingUtils.IsFishNew(self._data.id)
    KTool.SetActive(self.ImageNew, isNew)

    local gradient = self.GoodNode.transform:Find("Container/Icon").gameObject:GetComponent(typeof(CS.UnityEngine.UI.Extensions.Gradient2))
    gradient.enabled = not isCollect
end

function UIFishPoolFishAltasItemNode:FillEggsInfo()
    KTool.SetActive(self.ImageNew, false)
    KTool.SetActive(self.FishGrade, false)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data)

    CfUtils.RefeshGoodGo(self.GoodNode, vo.id, nil, 0.75, nil, function()
    end)
    --CfUtils.FillImage(self.GoodNode.transform:Find("Container/Bg"), GoodsUtils.GetFishBgByQualityType(vo.quality))

    SetButtonAction(self.Button, function()
        KTool.SetActive(self.ImageNew, false)
        if self._cb then
            self._cb()
        end
    end)

    local isUnlock = FishingUtils.IsUnlockEasterEggsId(self._data)
    KTool.SetActive(self.NotGet, not isUnlock)
    KTool.SetActive(self.GoodNode, isUnlock)
end

